import { motion } from 'framer-motion';
import clsx from 'clsx';
import './AcidTextMarquee.css';

export interface AcidTextMarqueeProps {
    text: string;
    speed?: number;
    repeat?: number;
    className?: string;
    direction?: 'left' | 'right';
}

export const AcidTextMarquee = ({ text, speed = 20, repeat = 4, className, direction = 'left' }: AcidTextMarqueeProps) => {
    return (
        <div className={clsx('ac-text-marquee-wrap', className)}>
            <motion.div
                className="ac-text-marquee-content"
                animate={{ x: direction === 'left' ? ['0%', '-50%'] : ['-50%', '0%'] }}
                transition={{ duration: speed, repeat: Infinity, ease: "linear" }}
            >
                {Array.from({ length: repeat }).map((_, i) => (
                    <span key={i} className="ac-text-marquee-item">
                        {text}
                        <span className="ac-marquee-separator">::</span>
                    </span>
                ))}
                {Array.from({ length: repeat }).map((_, i) => (
                    <span key={i + repeat} className="ac-text-marquee-item">
                        {text}
                        <span className="ac-marquee-separator">::</span>
                    </span>
                ))}
            </motion.div>
        </div>
    );
};

.ac-text-marquee-wrap {
    width: 100%;
    overflow: hidden;
    background: #000;
    border-top: 1px solid var(--ac-border-muted);
    border-bottom: 1px solid var(--ac-border-muted);
    padding: 0.75rem 0;
    white-space: nowrap;
    display: flex;
}

.ac-text-marquee-content {
    display: flex;
    align-items: center;
}

.ac-text-marquee-item {
    font-family: var(--font-mono);
    font-size: 0.9rem;
    color: var(--ac-text-primary);
    padding: 0 1rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}

.ac-marquee-separator {
    margin-left: 2rem;
    color: var(--ac-brand);
    font-weight: 800;
}
